3	import { useActionState, useState } from "react";
4	import { topUp } from "@/lib/actions";
5	import { Badge } from "@/components/ui/primitives";
6	
7	const PRESETS = [10, 25, 50, 100];
8	
9	function DemoTopUp() {
10	  const [state, action, pending] = useActionState(topUp, {});
11	  return (
12	    <div>
13	      <div className="mb-3 flex items-center gap-2">
14	        <Badge tone="amber">demo gateway</Badge>
15	        <span className="text-xs text-slate-500">
16	          Card payments are not configured — funds are credited instantly for testing.
17	        </span>
18	      </div>
19	      <form action={action} className="flex items-end gap-3">
20	        <div>
21	          <label className="label">Amount (USD)</label>
22	          <input
23	            className="input w-36"
24	            name="amount"
25	            type="number"
26	            min={1}
27	            max={1000}
28	            step="0.01"
29	            defaultValue={25}
30	          />
31	        </div>
32	        <button className="btn-primary" disabled={pending}>
33	          {pending ? "Adding…" : "Add funds"}
34	        </button>
35	        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
36	      </form>
37	    </div>
